function solve(A, x) {
  function cari(lo, hi) {
    if (lo > hi) return -1 // ruang pencarian kosong
    const mid = Math.floor((lo + hi) / 2)
    if (A[mid] === x) return mid
    if (A[mid] < x) return cari(mid + 1, hi)
    return cari(lo, mid - 1)
  }
  return cari(0, A.length - 1)
}
